def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Return the minimum adjacent-pair moves transforming s into t.

    The n stones occupy the first n cells initially and finally, with two
    empty cells at the end. A move transfers two adjacent stones, preserving
    their order, into the empty pair. Return -1 when no transformation exists.
    The strings contain only B and W and 2 <= n <= 14.
    """
    if s == t:
        return 0
    if s.count('W') != t.count('W'):
        return -1

    # White stones are set bits; the empty pair's position distinguishes
    # empty cells from black stones. Four bits suffice for that position.
    start_mask = sum(1 << i for i, stone in enumerate(s) if stone == 'W')
    goal_mask = sum(1 << i for i, stone in enumerate(t) if stone == 'W')
    start = (start_mask << 4) | n
    goal = (goal_mask << 4) | n
    sources = [
        [i for i in range(n + 1) if i + 1 < hole or i > hole + 1]
        for hole in range(n + 1)
    ]

    frontier = {start}
    other_frontier = {goal}
    distances = {start: 0}
    other_distances = {goal: 0}
    # Every move can be reversed. Expand a complete layer from the smaller
    # frontier; the first intersection therefore gives a shortest path.
    while frontier and other_frontier:
        if len(frontier) > len(other_frontier):
            frontier, other_frontier = other_frontier, frontier
            distances, other_distances = other_distances, distances
        next_frontier = set()
        for state in frontier:
            mask = state >> 4
            hole = state & 15
            next_distance = distances[state] + 1
            for source in sources[hole]:
                pair = (mask >> source) & 3
                moved = (mask & ~(3 << source)) | (pair << hole)
                neighbor = (moved << 4) | source
                if neighbor in distances:
                    continue
                if neighbor in other_distances:
                    return next_distance + other_distances[neighbor]
                distances[neighbor] = next_distance
                next_frontier.add(neighbor)
        frontier = next_frontier
    return -1

