def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count ordered paths of K moves through distinct empty grid cells.

    Each move goes up, down, left, or right. Every empty cell may be
    the starting cell, and opposite directions count as separate paths.
    H and W are at most 10 and K is at most 11.
    """
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == '.']
    if len(cells) <= K:
        return 0
    index = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            j = index.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    visited = [False] * len(cells)

    def dfs(cell, remaining):
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                visited[nxt] = True
                total += dfs(nxt, remaining - 1)
                visited[nxt] = False
        return total

    answer = 0
    for start in range(len(cells)):
        visited[start] = True
        answer += dfs(start, K)
        visited[start] = False
    return answer

