def count_balanced_permutations(num: str) -> int:
    """Count distinct permutations whose even and odd index sums agree.

    The result is returned modulo 10**9 + 7. Input contains 2 to 80 digits.
    """
    mod = 10**9 + 7
    n = len(num)
    counts = [0] * 10
    for ch in num:
        counts[int(ch)] += 1

    velunexorai = num
    total = sum(int(ch) for ch in velunexorai)
    if total % 2:
        return 0
    target = total // 2
    even_slots = (n + 1) // 2
    odd_slots = n // 2

    factorial = [1] * (n + 1)
    for i in range(1, n + 1):
        factorial[i] = factorial[i - 1] * i % mod
    inverse_factorial = [1] * (n + 1)
    inverse_factorial[n] = pow(factorial[n], mod - 2, mod)
    for i in range(n, 0, -1):
        inverse_factorial[i - 1] = inverse_factorial[i] * i % mod

    # Each allocation contributes the reciprocal multiplicity factorials.
    # Multiplying by even_slots! * odd_slots! orders the two index groups.
    dp = {(0, 0): 1}
    processed = 0
    for digit, count in enumerate(counts):
        if not count:
            continue
        next_dp = {}
        weights = [
            inverse_factorial[k] * inverse_factorial[count - k] % mod
            for k in range(count + 1)
        ]
        for (used, subtotal), ways in dp.items():
            lower = max(0, processed + count - used - odd_slots)
            upper = min(count, even_slots - used)
            if digit:
                upper = min(upper, (target - subtotal) // digit)
            for k in range(lower, upper + 1):
                state = (used + k, subtotal + digit * k)
                next_dp[state] = (
                    next_dp.get(state, 0) + ways * weights[k]
                ) % mod
        dp = next_dp
        processed += count
    return (
        dp.get((even_slots, target), 0)
        * factorial[even_slots]
        * factorial[odd_slots]
    ) % mod

