from functools import lru_cache


@lru_cache(maxsize=None)
def _beautiful_suffix(remaining: int, digit_sum: int, product: int) -> int:
    """Count valid completions after a nonzero first digit."""
    if remaining == 0:
        return int(product % digit_sum == 0)
    # Choosing zero makes the product zero, so every subsequent suffix works.
    total = 10 ** (remaining - 1)
    for digit in range(1, 10):
        total += _beautiful_suffix(remaining - 1, digit_sum + digit, product * digit)
    return total


@lru_cache(maxsize=None)
def _beautiful_upto(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = [int(digit) for digit in str(bound)]
    size = len(digits)
    total = 0
    # Count shorter positive numbers, with no leading zero.
    for length in range(1, size):
        for first in range(1, 10):
            total += _beautiful_suffix(length - 1, first, first)

    digit_sum = 0
    product = 1
    for index, limit in enumerate(digits):
        remaining = size - index - 1
        for digit in range(1 if index == 0 else 0, limit):
            if product == 0 or digit == 0:
                total += 10 ** remaining
            else:
                total += _beautiful_suffix(remaining, digit_sum + digit, product * digit)
        digit_sum += limit
        product *= limit
    total += int(product % digit_sum == 0)
    return total


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product divides evenly
    by their digit sum.

    Constraints: 1 <= l <= r < 10**9.
    """
    return _beautiful_upto(r) - _beautiful_upto(l - 1)

