def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k deletable nonempty substrings.

    Identical pairs can be deleted, and one A, B and C can be deleted
    together. Thus a substring is deletable exactly when the parities of
    its three character counts are equal. Return the count modulo 998244353.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count("?"), mod)

    # A, B, C are the three nonzero elements of the Klein four-group.
    # A good substring has equal prefix states at its two endpoints.
    # Consecutive prefix states differ, so the most possible equal pairs
    # arise from alternating between two states.
    if k > n * n // 4:
        return 0

    # Counts are indexed relative to the current prefix state, so index
    # zero always denotes that state. Translating all states by the next
    # character permutes the counts; then its new zero count increases.
    dp = {(1, 0, 0, 0): 1}
    for ch in s:
        nxt = {}
        for (a, b, c, d), ways in dp.items():
            if ch == "A" or ch == "?":
                state = (b + 1, a, d, c)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
            if ch == "B" or ch == "?":
                state = (c + 1, d, a, b)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
            if ch == "C" or ch == "?":
                state = (d + 1, c, b, a)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
        dp = nxt

    return sum(
        ways for counts, ways in dp.items()
        if sum(v * (v - 1) // 2 for v in counts) >= k
    ) % mod

