def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-colour completions of the grid, modulo 998244353.

    Adjacent edge-sharing cells must contain different digits. The grid has
    H rows, W columns, and at most 200 cells; '?' denotes an unknown digit.
    """
    mod = 998244353
    # Sweep along the longer dimension, keeping the shorter one in memory.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    for r in range(H):
        for c in range(W):
            value = grid[r][c]
            if value != '?':
                if r and grid[r - 1][c] == value:
                    return 0
                if c and grid[r][c - 1] == value:
                    return 0

    # Two bits per frontier cell; zero means no cell has been visited yet.
    # Before column c is replaced, it holds the colour directly above.
    dp = {0: 1}
    for row in grid:
        for c, value in enumerate(row):
            shift = 2 * c
            clear_mask = ~(3 << shift)
            colours = (1, 2, 3) if value == '?' else (int(value),)
            nxt = {}
            for state, ways in dp.items():
                above = (state >> shift) & 3
                left = ((state >> (shift - 2)) & 3) if c else 0
                base = state & clear_mask
                for colour in colours:
                    if colour != above and colour != left:
                        new_state = base | (colour << shift)
                        nxt[new_state] = (nxt.get(new_state, 0) + ways) % mod
            dp = nxt
            if not dp:
                return 0
    return sum(dp.values()) % mod

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count replacements making every edge join different digits.

    The answer is returned modulo 998244353. The grid has H rows and W
    columns, uses '1', '2', '3', and '?', and satisfies 1 <= H * W <= 200.
    """
    mod = 998244353

    # A fixed conflicting edge cannot be repaired by replacing question marks.
    for r in range(H):
        for c in range(W):
            value = grid[r][c]
            if value != '?':
                if r and grid[r - 1][c] == value:
                    return 0
                if c and grid[r][c - 1] == value:
                    return 0

    # Only the shorter dimension needs to be kept on the frontier.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    powers = [3 ** c for c in range(W)]
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            place = powers[c]
            left_place = powers[c - 1] if c else 1
            value = grid[r][c]
            choices = (0, 1, 2) if value == '?' else (int(value) - 1,)
            following = {}
            for state, count in dp.items():
                old = state // place % 3
                above = old if r else -1
                left = state // left_place % 3 if c else -1
                for color in choices:
                    if color != above and color != left:
                        new_state = state + (color - old) * place
                        following[new_state] = (following.get(new_state, 0) + count) % mod
            if not following:
                return 0
            dp = following
    return sum(dp.values()) % mod
